/**
 * A assinatura do Criador na natureza — porte de `componentes/viz/girassol.js`.
 *
 * O capítulo do girassol nasce de uma regra de uma linha só: a semente `i` fica
 * a `C·√i` do centro, girada `i × ângulo` em relação à anterior. Todo o mistério
 * está no ÂNGULO. A um grau do ângulo áureo (~137,5°) as sementes se alinham em
 * raios e abrem buracos; no ângulo áureo — o único número que nenhuma fração
 * aproxima bem — elas nunca se alinham, e por isso empacotam sem sobra.
 *
 * Por isso o controle é o ângulo, e não o número de sementes: é ele que separa a
 * flor da bagunça. Quando fecha, a flor desabrocha.
 *
 * **Three.js virou PixiJS** (ver `viz/cena3d.ts`): as sementes, que lá eram 360
 * malhas de esfera, aqui são nuvens de pontos em faixas radiais — a projeção de
 * uma esfera é um círculo, e é isso que uma semente é na tela.
 */

import type { No, Vetor3 } from '../../../viz/cena3d.ts';
import { montar3d } from '../../../viz/cena3d.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const SEMENTES = 360;
/** Fator de espalhamento: raio = C·√i. */
const C = 0.3;
const AUREO = 137.5;
/** Faixas radiais; cada uma tem a sua cor, e juntas dão o degradê do capítulo. */
const FAIXAS = 8;
const PETALAS = 24;

/** HSL → 0xRRGGBB, para o degradê do miolo à borda. */
function hsl(h: number, s: number, l: number): number {
  const f = (n: number): number => {
    const k = (n + h * 12) % 12;
    const a = s * Math.min(l, 1 - l);
    return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))));
  };
  return (f(0) << 16) | (f(8) << 8) | f(4);
}

const girassol: FabricaViz = (canvas): VizDoPuzzle =>
  montar3d(
    canvas,
    (cena) => {
      const faixas: (No & { pontos: readonly Vetor3[]; cor: number })[] = [];
      for (let i = 0; i < FAIXAS; i++) {
        faixas.push(cena.pontos({ pontos: [], cor: 0x8a93b5, tamanho: 0.17 }));
      }

      // As pétalas existem desde o início e só aparecem quando a flor fecha —
      // criá-las na hora custaria um engasgo bem no quadro da recompensa.
      const petalas: No[] = [];
      for (let i = 0; i < PETALAS; i++) {
        const angulo = (i / PETALAS) * Math.PI * 2;
        const de: Vetor3 = [Math.cos(angulo) * 6.4, 0.05, Math.sin(angulo) * 6.4];
        const ate: Vetor3 = [Math.cos(angulo) * 7.9, 0.05, Math.sin(angulo) * 7.9];
        const petala = cena.tubo({ pontos: [de, ate], cor: 0xffc107, raio: 0.16 });
        petala.visivel = false;
        petalas.push(petala);
      }

      const status = cena.rotulo('', { pos: [0, 4.2, 0], tamanho: 15 });

      cena.animar(() => {
        cena.camera.girar(0.003, 0);
      });

      return {
        aplicar(estado) {
          const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;
          const info = (estado.info ?? {}) as Readonly<Record<string, unknown>>;

          const bruto = Number(valores.ang);
          const angulo = Number.isFinite(bruto) ? bruto : AUREO;
          const ok = info.ok === true;
          const rad = angulo * (Math.PI / 180);

          const porFaixa: Vetor3[][] = Array.from({ length: FAIXAS }, () => []);
          for (let i = 0; i < SEMENTES; i++) {
            const r = C * Math.sqrt(i);
            const a = i * rad;
            const faixa = Math.min(FAIXAS - 1, Math.floor((i / SEMENTES) * FAIXAS));
            // Domo leve: o miolo é mais alto que a borda, como no capítulo real.
            porFaixa[faixa]?.push([Math.cos(a) * r, 0.5 - 0.01 * r * r, Math.sin(a) * r]);
          }

          for (let i = 0; i < FAIXAS; i++) {
            const no = faixas[i];
            if (no === undefined) continue;

            const f = i / (FAIXAS - 1);
            no.pontos = porFaixa[i] ?? [];
            // Dourado quando empacota; azul frio quando sobram buracos.
            no.cor = ok
              ? hsl(0.12 + f * 0.03, 0.85, 0.26 + f * 0.3)
              : hsl(0.58 - f * 0.04, 0.3, 0.4 + f * 0.16);
          }

          for (const petala of petalas) petala.visivel = ok;

          status.texto = ok
            ? `${angulo.toFixed(1).replace('.', ',')}° · empacotamento perfeito ✓`
            : `${angulo.toFixed(1).replace('.', ',')}° · alvo 137,5° (o ângulo áureo)`;
        },
      };
    },
    { cameraPos: [0, 9.5, 6.5], alvo: [0, 0, 0], fov: 42 },
  );

export default girassol;
